var kthDistinct = function(arr, k) {
    const counts = new Map();
    for (const s of arr) {
        counts.set(s, (counts.get(s) || 0) + 1);
    }
    let distinctIndex = 0;
    for (const s of arr) {
        if (counts.get(s) === 1) {
            distinctIndex++;
            if (distinctIndex === k) return s;
        }
    }
    return "";
};
